using System.Text.Json;
using VibeMiner.Builds;
using VibeMiner.Concepts.Items;
using VibeMiner.Concepts.Creatures;
var pairs=new (string Text,string Query)[]{("Hello","HEL"),("café","É"),("straße","STRASSE"),("ß","ẞ"),("I","ı"),("i","İ"),("ſ","s"),("K","k"),("Σςσ","σσΣ"),("𐐀","𐐨"),("abc",""),("a😀b","😀"),("abcdef","gh"),("µ","Μ"),("ﬀ","FF"),("\u0345","Ι"),("é","e\u0301")};
var matches=pairs.Select(p=>new{text=p.Text,query=p.Query,matches=p.Text.Contains(p.Query,StringComparison.OrdinalIgnoreCase)}).ToArray();
var inputs=new[]{"","a",new string('a',128),new string('a',129),string.Concat(Enumerable.Repeat("😀",128)),string.Concat(Enumerable.Repeat("😀",129)),"x\0y","\ud800","\udc00","\ud800x","é"};
var validation=inputs.Select(s=>new{units=string.Concat(s.Select(ch=>((int)ch).ToString("X4"))),valid=ItemQueries.IsValidQuery(s)}).ToArray();
var build=new BuildRef("wow",new string('a',32),new string('b',32),"us");
var cursors=new[]{"a","é","😀"," İ","ß"}.Select(q=>{var binding=ItemQueries.Binding(build,"enUS",new ItemQuery(q,null,17));var creatureBinding=CreatureQueries.Binding(build,"enUS",new CreatureQuery(q,null,17));return new{query=q,binding,creatureBinding,cursor=ItemQueries.EncodeCursor(new ItemCursor(binding,7,new string('f',64),new string('c',32)))};}).ToArray();
var root=new{matches,validation,cursors};
Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(args[0]))!);
File.WriteAllText(args[0],JsonSerializer.Serialize(root));
